const K = new Uint32Array(64);
const H0 = new Uint32Array(8);
{
    const primes = [];
    for (let n = 2; primes.length < 64; n++)
        if (primes.every((p) => n % p))
            primes.push(n);
    const frac = (x) => ((x - Math.floor(x)) * 2 ** 32) >>> 0;
    primes.forEach((p, i) => { K[i] = frac(Math.cbrt(p)); if (i < 8)
        H0[i] = frac(Math.sqrt(p)); });
}
const ror = (x, n) => (x >>> n) | (x << (32 - n));
function fingerprint(text) {
    const bytes = new TextEncoder().encode(text);
    const n = bytes.length;
    const words = (((n + 8) >> 6) + 1) << 4;
    const w = new Uint32Array(words);
    for (let i = 0; i < n; i++)
        w[i >> 2] |= bytes[i] << (24 - (i & 3) * 8);
    w[n >> 2] |= 0x80 << (24 - (n & 3) * 8);
    w[words - 1] = n * 8;
    const h = H0.slice();
    const m = new Uint32Array(64);
    for (let b = 0; b < words; b += 16) {
        for (let t = 0; t < 16; t++)
            m[t] = w[b + t];
        for (let t = 16; t < 64; t++) {
            const x = m[t - 15], y = m[t - 2];
            m[t] = m[t - 16] + (ror(x, 7) ^ ror(x, 18) ^ (x >>> 3)) + m[t - 7] + (ror(y, 17) ^ ror(y, 19) ^ (y >>> 10));
        }
        let [a, bb, c, d, e, f, g, hh] = h;
        for (let t = 0; t < 64; t++) {
            const t1 = (hh + (ror(e, 6) ^ ror(e, 11) ^ ror(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + m[t]) | 0;
            const t2 = ((ror(a, 2) ^ ror(a, 13) ^ ror(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0;
            hh = g;
            g = f;
            f = e;
            e = (d + t1) | 0;
            d = c;
            c = bb;
            bb = a;
            a = (t1 + t2) | 0;
        }
        h[0] += a;
        h[1] += bb;
        h[2] += c;
        h[3] += d;
        h[4] += e;
        h[5] += f;
        h[6] += g;
        h[7] += hh;
    }
    return h[0].toString(16).padStart(8, "0");
}

